#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    const long long MOD = 1000000007LL;

    int q;
    cin >> q;
    while (q--) {
        int n;
        cin >> n;
        vector<long long> a(n);
        for (int i = 0; i < n; ++i) cin >> a[i];

        vector<pair<long long, long long>> st; // (最小值, 段数)
        long long cur = 0, ans = 0;

        for (int k = 1; k <= n; ++k) {
            long long x = a[k - 1];
            long long cnt = 1;
            while (!st.empty() && st.back().first >= x) {
                cur = (cur - st.back().first * st.back().second) % MOD;
                cnt += st.back().second;
                st.pop_back();
            }
            st.push_back({x, cnt});
            cur = (cur + x * cnt) % MOD;
            if (cur < 0) cur += MOD;
            ans = (ans + cur * (n - k + 1)) % MOD;
        }
        cout << ans << '\n';
    }
    return 0;
}
